{
  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    total_alloc = sum(alloc)
    remaining = budget - total_alloc
    while remaining > 0:
        best_idx = -1
        best_ratio = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                ratio = seg['importance'] / (alloc[i] + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        remaining -= 1
    by_name = {}
    for i, seg in enumerate(segments):
        by_name[seg['name']] = alloc[i]
    total = sum(alloc)
    return {'allocations': alloc, 'by_name': by_name, 'total': total}"
